contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(v > 0);
        require(address(this).balance >= v);

        (uint uBefore, uint bBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.Put{value: v}(0); if (__ESBMC_reverted()) return;

        (uint uAfter, uint bAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(bAfter + cBalAfter == bBefore + cBalBefore + v);
    }

    receive() external payable {}
}

