pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(address(this).balance >= v);
        uint256 uBefore;
        uint256 bBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { uBefore = __r0; bBefore = __r1; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Put{value: v}(0) {} catch { return; }
        uint256 uAfter;
        uint256 bAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { uAfter = __r0; bAfter = __r1; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(bAfter + cBalAfter == bBefore + cBalBefore + v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
